"use client";

import { AnimatePresence, motion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type PointerEvent, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** A point of a stroke, in the pad's own units: 300 wide by 100 tall, whatever size the pad renders at. */
export type SignaturePoint = { x: number; y: number };

/** A signature is either drawn strokes or a typed name, never both. An empty one has no strokes and no name. */
export type SignatureValue = { strokes: SignaturePoint[][]; name: string };

/** Props for a signature pad. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export type SignaturePadProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "children" | "defaultValue"> & {
  value?: SignatureValue;
  defaultValue?: SignatureValue;
  /**
   * Runs when a stroke ends, the typed name changes or the pad is cleared. `dataUrl` is the signature as an
   * SVG image, or an empty string when the pad is empty.
   */
  onValueChange?: (value: SignatureValue, dataUrl: string) => void;
  /** The visible name of the pad. */
  label?: string;
  /** The visible label of the typed-name input, the path for people who cannot draw. */
  nameLabel?: string;
};

const WIDTH = 300;
const HEIGHT = 100;
const EMPTY: SignatureValue = { strokes: [], name: "" };
// Points closer together than this are dropped, which removes the jitter of a slow hand.
const MIN_GAP = 1.5;
// The wipe is a short fade, which reduced motion may keep.
const WIPE: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };

const round = (n: number) => Math.round(n * 10) / 10;

// A typed name is drawn 30 units tall, and smaller when it would run past the 252 units of the baseline.
// An italic letter is about half as wide as it is tall.
const NAME_SIZE = 30;
const nameSizeOf = (name: string) => Math.min(NAME_SIZE, Math.floor(252 / (0.5 * Math.max(1, name.length))));

// A curve through the midpoints of the samples, so corners between pointer events come out round.
function pathOf(points: SignaturePoint[]) {
  const [first, ...rest] = points;
  if (!first) return "";
  if (rest.length === 0) return `M${round(first.x)} ${round(first.y)}l0.01 0`;
  let path = `M${round(first.x)} ${round(first.y)}`;
  for (let index = 1; index < points.length - 1; index += 1) {
    const point = points[index];
    const next = points[index + 1];
    path += `Q${round(point.x)} ${round(point.y)} ${round((point.x + next.x) / 2)} ${round((point.y + next.y) / 2)}`;
  }
  const last = points[points.length - 1];
  return `${path}L${round(last.x)} ${round(last.y)}`;
}

function dataUrlOf({ strokes, name }: SignatureValue) {
  if (strokes.length === 0 && !name) return "";
  const safeName = name.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const body = name
    ? `<text x="150" y="64" text-anchor="middle" font-size="${nameSizeOf(name)}" font-style="italic" fill="oklch(0.2 0 0)" stroke="none">${safeName}</text>`
    : strokes.map((stroke) => `<path d="${pathOf(stroke)}"/>`).join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${WIDTH} ${HEIGHT}" fill="none" stroke="oklch(0.2 0 0)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

/**
 * Collects a signature. The person draws with a pointer or a finger and the stroke comes out smoothed, or they
 * type their name and the pad shows it as the signature. "Clear" wipes the pad with a quick fade.
 */
export function SignaturePad({
  value,
  defaultValue = EMPTY,
  onValueChange,
  label = "Signature",
  nameLabel = "Or type your name",
  className,
  ...divProps
}: SignaturePadProps) {
  const [ownValue, setOwnValue] = useState(defaultValue);
  const [drawing, setDrawing] = useState(false);
  // The stroke in progress is painted straight onto its path. A React state
  // update per pointer sample would re-render the pad on every move.
  const livePoints = useRef<SignaturePoint[]>([]);
  const livePath = useRef<SVGPathElement>(null);
  // Each wipe starts a new layer. The old layer keeps what it showed and fades out.
  const [layer, setLayer] = useState(0);
  const id = useId();
  const signature = value ?? ownValue;
  const empty = signature.strokes.length === 0 && !signature.name && !drawing;

  const commit = (next: SignatureValue) => {
    if (value === undefined) setOwnValue(next);
    onValueChange?.(next, dataUrlOf(next));
  };

  const pointOf = (event: PointerEvent<SVGSVGElement>): SignaturePoint => {
    const box = event.currentTarget.getBoundingClientRect();
    if (box.width === 0 || box.height === 0) return { x: event.clientX, y: event.clientY };
    return { x: ((event.clientX - box.left) / box.width) * WIDTH, y: ((event.clientY - box.top) / box.height) * HEIGHT };
  };

  const endStroke = (event: PointerEvent<SVGSVGElement>) => {
    if (!drawing) return;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);
    setDrawing(false);
    livePath.current?.setAttribute("d", "");
    // Drawing replaces a typed name.
    commit({ strokes: [...signature.strokes, livePoints.current], name: "" });
  };

  const clear = () => {
    if (empty) return;
    setLayer((count) => count + 1);
    commit(EMPTY);
  };

  const described = signature.name ? signature.name : signature.strokes.length > 0 || drawing ? "drawn" : "empty";

  return (
    <div {...divProps} className={cn("flex w-full flex-col gap-2 text-sm", className)}>
      <div className="flex items-center justify-between gap-4">
        <span className="font-medium text-foreground">{label}</span>
        <button
          type="button"
          // Not disabled when empty: a disabled button would drop keyboard focus right after the wipe.
          aria-disabled={empty || undefined}
          onClick={clear}
          className={cn(
            "relative cursor-pointer rounded-md px-2 py-0.5 font-medium text-foreground outline-none before:absolute before:-inset-y-3 before:inset-x-0",
            "focus-visible:ring-2 focus-visible:ring-ring",
            empty && "cursor-not-allowed text-muted-foreground",
          )}
        >
          Clear
        </button>
      </div>
      <svg
        role="img"
        aria-label={`${label}: ${described}`}
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        onPointerDown={(event) => {
          if (event.button !== 0) return;
          event.currentTarget.setPointerCapture?.(event.pointerId);
          // A typed name gives way to the drawing, with the same fade as a wipe.
          if (signature.name) setLayer((count) => count + 1);
          livePoints.current = [pointOf(event)];
          livePath.current?.setAttribute("d", pathOf(livePoints.current));
          setDrawing(true);
        }}
        onPointerMove={(event) => {
          if (!drawing) return;
          const point = pointOf(event);
          const last = livePoints.current[livePoints.current.length - 1];
          if (Math.hypot(point.x - last.x, point.y - last.y) < MIN_GAP) return;
          livePoints.current = [...livePoints.current, point];
          livePath.current?.setAttribute("d", pathOf(livePoints.current));
        }}
        onPointerUp={endStroke}
        onPointerCancel={endStroke}
        // touch-none keeps a finger stroke from scrolling the page.
        className="aspect-3/1 w-full cursor-crosshair touch-none rounded-lg border border-border bg-background text-foreground"
      >
        <path d="M24 78H276" strokeWidth="1" className="stroke-border" />
        <AnimatePresence initial={false}>
          <motion.g
            key={layer}
            exit={{ opacity: 0 }}
            transition={WIPE}
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {signature.name && !drawing ? (
              // A long name gets smaller type, so it never runs past the edges of the pad.
              <text x="150" y="64" textAnchor="middle" fontSize={nameSizeOf(signature.name)} fill="currentColor" stroke="none" className="italic">
                {signature.name}
              </text>
            ) : (
              signature.strokes.map((stroke, index) => <path key={index} d={pathOf(stroke)} />)
            )}
          </motion.g>
        </AnimatePresence>
        {/* Outside the fading layers: a layer that leaves would take the ref with it. */}
        <path ref={livePath} fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
        <label htmlFor={`${id}-name`} className="shrink-0 text-muted-foreground">
          {nameLabel}
        </label>
        <input
          id={`${id}-name`}
          type="text"
          autoComplete="name"
          spellCheck={false}
          value={signature.name}
          onChange={(event) => {
            // Typing replaces a drawing, and the drawing fades like a wipe.
            if (signature.strokes.length > 0) setLayer((count) => count + 1);
            commit({ strokes: [], name: event.target.value });
          }}
          // 16px text on a phone stops iOS from zooming into the field.
          className="h-11 min-w-44 flex-1 rounded-lg border border-border bg-background px-3 text-base text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring sm:text-sm"
        />
      </div>
    </div>
  );
}
